sysevent_script_action.script:
queueIncidentImport();

function queueIncidentImport() {

    // The job we will run, via subflow
    const scheduled_import_set_sys_id = getSysId(
        gs.getCurrentApplicationId(),
        "scheduled_import_set",
        "Incident Import");

    // The data source holding the attachment we will import
    const from_data_source_sys_id = getSysId(
        gs.getCurrentApplicationId(),
        "sys_data_source",
        "Incident Data Queue");

    // The data source we will move the attachment to before import
    const to_data_source_sys_id = getSysId(
        gs.getCurrentApplicationId(),
        "sys_data_source",
        "Incident Data");

    var inputs = {};
    inputs['scheduled_import_set_sys_id'] = scheduled_import_set_sys_id;
    inputs['from_data_source_sys_id'] = from_data_source_sys_id;
    inputs['to_data_source_sys_id'] = to_data_source_sys_id;

    sn_fd.FlowAPI
        .getRunner()
        .subflow('x_42999_sequenti_0.queue_up_incident_import')
        .inBackground()
        .withInputs(inputs)
        .run();
}

function getSysId(app_id, tableName, name) {
    var result = null;
    var gr = new GlideRecord(tableName);
    gr.addQuery("sys_scope", app_id);
    gr.addQuery("name", name);
    gr.setLimit(1);
    gr.query();
    if (gr.next()) result = gr.getValue("sys_id");
    return result;
}
